def update_settings(self, **kwargs):
        """
        Update the router settings.
        """
        # only the following settings are allowed to be configured
        _allowed_settings = [
            "routing_strategy_args",
            "routing_strategy",
            "routing_groups",
            "allowed_fails",
            "cooldown_time",
            "num_retries",
            "timeout",
            "max_retries",
            "retry_after",
            "fallbacks",
            "context_window_fallbacks",
            "retry_policy",
            "model_group_retry_policy",
            "model_group_alias",
            "enable_weighted_failover",
            "enable_tag_filtering",
        ]

_int_settings = [
            "timeout",
            "num_retries",
            "retry_after",
            "allowed_fails",
            "cooldown_time",
        ]

_existing_router_settings = self.get_settings()
        rebuild_routing_groups = False
        relink_lar1_from_args = False
        for var in kwargs:
            if var in _allowed_settings:
                if var in _int_settings:
                    _casted_value = int(kwargs[var])
                    setattr(self, var, _casted_value)
                elif var == "routing_groups":
                    self._routing_groups_input = kwargs[var]
                    rebuild_routing_groups = True
                elif var == "retry_policy":
                    value = kwargs[var]
                    if isinstance(value, dict):
                        value = RetryPolicy(**value)
                    if value is None or isinstance(value, RetryPolicy):
                        setattr(self, var, value)
