def _filter_deployments_by_model_access_groups(
        self,
        model: str,
        healthy_deployments: List,
        request_kwargs: Optional[Dict],
        request_team_id: Optional[str],
    ) -> List:
        """
        Restrict candidate deployments to caller-authorized model access groups.

This is only applied when:
        - request metadata includes `user_api_key_auth`, and
        - caller permissions for this model are access-group-only
          (no explicit model, wildcard, or all-proxy grants).
        """
        if not healthy_deployments or request_kwargs is None:
            return healthy_deployments

metadata = request_kwargs.get("metadata") or {}
        litellm_metadata = request_kwargs.get("litellm_metadata") or {}
        user_api_key_auth = metadata.get("user_api_key_auth") or litellm_metadata.get("user_api_key_auth")
        if user_api_key_auth is None:
            return healthy_deployments

object_models = set(getattr(user_api_key_auth, "models", []) or [])
        object_team_models = set(getattr(user_api_key_auth, "team_models", []) or [])
        allowed_models = object_models | object_team_models
        if not allowed_models:
            return healthy_deployments

# If caller has direct model/wildcard/all-proxy access, do not constrain
        # deployment choice by access group.
        if model in allowed_models or "*" in allowed_models or "all-proxy-models" in allowed_models:
            return healthy_deployments

access_groups_for_model = self.get_model_access_groups(model_name=model, team_id=request_team_id)
        if len(access_groups_for_model) == 0:
            return healthy_deployments","content_hash":"25bb3ce08af01ff317d03d3d0dec109d1b1aed0efef6cd15e9de6764a3abf789","chunk_metadata":{"ordinal":277,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/kaitlyn-nguyen/litellm-retry-after-v2","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00277","vector":{"bm25":{"indices":[19522071,21141582,99968580,117848935,125777136,131900689,148299209,152217691,192819851,213600005,219346761,228353112,268904186,269443847,340311674,340581898,344065877,390204765,393329829,402167784,403465192,438080992,439281281,448220673,454222729,455026286,491396510,505117043,511212064,516762017,520409122,523661903,550693654,563226112,572399988,573824723,589492662,630986436,632657554,655955059,684900361,728008763,752368150,757424159,764297089,766710245,772165269,775532692,776168496,780249753,795797866,806276788,809654831,813056149,823134346,856984290,888000370,920073456,926244272,930883039,953378023,967714644,999038032,1004164276,1007875655,1036332678,1036623567,1110626798,1112552363,1120495519,1132748958,1151308235,1169853166,1172383616,1199422005,1245654145,1254444102,1258039968,1263925004,1264091051,1297380231,1331432587,1352835661,1406904314,1429051991,1430125705,1443829736,1452893298,1455480578,1468290209,1492004250,1515372845,1519078073,1539641452,1572251935,1590456296,1634511095,1636998148,1646401716,1662505136,1668369950,1678348498,1679626713,1701260558,1721384439,1727379255,1748272243,1751311563,1754526443,1761927089,1763574823,1780580861,1782951321,1810453357,1830646559,1833610515,1838689002,1845866462,1853176582,1952791762,1996864093,1998848851,2007450916,2021799277,2046009338,2050864532,2064885619,2084206835,2092433587,2126841918,2128973781,2134303291],"values":[1.0538923,1.4251012,1.0538923,1.0538923,1.0538923,1.8624339,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.0538923,1.42510