async def _run_routing_plugins(
        self,
        model: str,
        request_kwargs: dict,
        messages: list[dict[str, Any]] | None,
    ) -> RoutingContext:
        """
        Build a RoutingContext for `model`, run it through `self.routing_plugins`
        in order, then stash the narrowed candidate list and accumulated signals
        onto `request_kwargs["metadata"]` so `_filter_by_routing_plugin_candidates`
        (called later, during healthy-deployment filtering) can consume them.
        """
        from litellm.litellm_core_utils.prompt_templates.factory import (
            resolve_structured_messages,
        )

deployments = self.get_model_list(model_name=model) or []
        candidate_models = [
            d["litellm_params"]["model"] for d in deployments if d.get("litellm_params", {}).get("model")
        ]

metadata_key = self._get_metadata_variable_name_from_kwargs(request_kwargs)
        metadata = request_kwargs.setdefault(metadata_key, {})

context = RoutingContext(
            raw_messages=messages or [],
            structured_messages=resolve_structured_messages(messages=messages, request_kwargs=request_kwargs) or [],
            candidate_models=candidate_models,
            metadata=metadata,
        )

for plugin in self.routing_plugins:
            context = await plugin.run(context)","content_hash":"3ce0b16f6424c11f46bfcdd771a98495fec3da77f131007f3097e7a0f955f75e","chunk_metadata":{"ordinal":288,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/kaitlyn-nguyen/litellm-retry-after-v2","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00288","vector":{"bm25":{"indices":[19522071,21141582,117848935,131900689,152217691,182765111,233592972,241200325,242555882,269443847,272151644,307919594,324964102,376835143,380541707,393329829,402167784,448220673,454222729,491396510,493065660,505117043,505715833,523661903,550693654,563226112,567762709,572399988,647126174,673001843,684900361,689573637,757424159,766710245,772165269,795106543,806276788,821807421,888561024,896588784,917314569,920073456,926244272,951234652,959731968,1003798966,1009084850,1050315610,1058917028,1119753640,1132748958,1135795808,1139959774,1170138678,1172383616,1219477914,1254567565,1258039968,1263925004,1297380231,1299665196,1320276626,1331432587,1349791844,1418987760,1430125705,1454755048,1469602885,1492004250,1515372845,1518651811,1519078073,1526557164,1531299186,1567747819,1581361369,1590456296,1605015950,1641924751,1649418775,1653414040,1662320396,1683855105,1701593959,1710438329,1758234468,1763574823,1778163201,1785447155,1810453357,1815029495,1818572693,1819509527,1830646559,1838689002,1853176582,1972720242,1998848851,2021799277,2045916435,2047305964,2064885619,2065015680,2143830595],"values":[1.0982839,1.0982839,1.6487119,1.6487119,1.4651405,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.0982839,1.7589006,1.0982839,1.0982839,1.0982839,1.0982839,1.6487119,1.8848728,1.0982839,1.6487119,1.0982839,1.0982839,1.0982839,1.6487119,1.0982839,1.0982839,1.0982839,1.0982839,1.4651405,1.7589006,1.6487119,1.0982839,1.7589006,2.0161417,1.0982839,1.4651405,1.0982839,1.0982839,1.0982839,1.6487119,1.0982839,1.09828