async def _run_routing_plugins(
        self,
        model: str,
        request_kwargs: dict,
        messages: list[dict[str, Any]] | None,
    ) -> RoutingContext:
        """
        Build a RoutingContext for `model`, run it through `self.routing_plugins`
        in order, then stash the narrowed candidate list and accumulated signals
        onto `request_kwargs["metadata"]` so `_filter_by_routing_plugin_candidates`
        (called later, during healthy-deployment filtering) can consume them.
        """
        from litellm.litellm_core_utils.prompt_templates.factory import (
            resolve_structured_messages,
        )

deployments = self.get_model_list(model_name=model) or []
        candidate_models = [
            d["litellm_params"]["model"] for d in deployments if d.get("litellm_params", {}).get("model")
        ]

metadata_key = self._get_metadata_variable_name_from_kwargs(request_kwargs)
        metadata = request_kwargs.setdefault(metadata_key, {})

context = RoutingContext(
            raw_messages=messages or [],
            structured_messages=resolve_structured_messages(messages=messages, request_kwargs=request_kwargs) or [],
            candidate_models=candidate_models,
            metadata=metadata,
        )

for plugin in self.routing_plugins:
            context = await plugin.run(context)","content_hash":"5d410ab7b7349177cfe091bb99c6ffa02d35ba1d8b3ee370a6dcc00e0dbbf71c","chunk_metadata":{"ordinal":295,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/kaitlyn-nguyen/litellm-retry-after-v2","team":""}}},"conflict_id":null,"change_id":"qdrant:74f113969685e83f237ef2c3"},{"table":"knowledge","key":{"id":"enterprise_cb873e2345a508fa44720d93:00296"},"change":"modified","before":{"id":"enterprise_cb873e2345a508fa44720d93:00296","vector":{"bm25":{"indices":[92787142,93552248,102120688,136345932,150695120,152217691,166093682,176587294,182765111,257581069,307919594,325678202,390204765,402167784,403465192,405807530,443994268,448220673,454222729,455026286,482263480,491396510,505117043,550693654,563226112,599296923,599316540,608954612,609270800,636372192,663089258,671481495,672811249,684900361,690815750,710818858,715022825,728008763,766710245,772165269,780249753,834846576,888000370,917314569,920073456,926244272,956524161,965664421,989116115,997012898,1003647919,1009084850,1036623567,1050315610,1060439614,1135795808,1153012442,1172010017,1172383616,1258039968,1297380231,1299665196,1331432587,1430125705,1449660732,1519078073,1581361369,1605015950,1635977013,1637669348,1653414040,1661516011,1662505136,1717991430,1751311563,1763574823,1790752915,1810453357,1838689002,1845866462,1853176582,1882140086,1887486930,1972720242,1998848851,2021799277,2036920246,2064885619,2084206835,2086848750,2122579230,2143830595],"values":[1.1723564,1.5296035,1.1723564,1.1723564,1.1723564,1.7025393,1.1723564,1.1723564,1.1723564,1.1723564,1.1723564,1.9551677,1.5296035,1.5296035,1.1723564,1.1723564,1.8045498,1.1723564,1.1723564,1.5296035,1.5296035,1.5296035,1.1723564,1.5296035,1.7025393,1.1723564,1.5296035,1.1723564,1.1723564,1.1723564,1.1723564,1.1723564,1.9195638,1.1723564,1.1723564,1.1723564,1.1723564,1.1723564,1.1723564,1.5296035,1.1723564,1.1723564,1.5296035,1.8045498,1.5296035,1.1723564,1.1723564