def _filter_cooldown_deployments(
        self, healthy_deployments: List[Dict], cooldown_deployments: List[str]
    ) -> List[Dict]:
        """
        Filters out the deployments currently cooling down from the list of healthy deployments

Args:
            healthy_deployments: List of healthy deployments
            cooldown_deployments: List of model_ids cooling down. cooldown_deployments is a list of model_id's cooling down, cooldown_deployments = ["16700539-b3cd-42f4-b426-6a12a1bb706a", "16700539-b3cd-42f4-b426-7899"]

Returns:
            List of healthy deployments
        """
        if verbose_router_logger.isEnabledFor(logging.DEBUG):
            verbose_router_logger.debug(f"cooldown deployments: {cooldown_deployments}")
        # Convert to set for O(1) lookup and use list comprehension for O(n) filtering
        cooldown_set = set(cooldown_deployments)
        return [deployment for deployment in healthy_deployments if deployment["model_info"]["id"] not in cooldown_set]

def _filter_blocked_deployments(self, healthy_deployments: List[Dict]) -> List[Dict]:
        """
        Filters out deployments that an admin has paused via `LiteLLM_ProxyModelTable.blocked`.

Applied alongside the cooldown filter on every routing entry point that calls
        `_common_checks_available_deployment` directly — the primary sync/async path,
        the sync pass-through path, and the retry / health-check helpers — so paused
        deployments never serve a request. The async pass-through path inherits this
        filter through its delegation to `async_get_healthy_deployments`.
        """
        return [
            deployment
            for deployment in healthy_deployments
            if (deployment.get("model_info") or {}).get("blocked") is not True
        ]","content_hash":"8cf825ddd9cb1840115f7b24ea3c0bbe3822e4c0cd449ef77d4f59f3f57728db","chunk_metadata":{"ordinal":308,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/kaitlyn-nguyen/litellm-retry-after-v2","team":""}}},"conflict_id":null,"change_id":"qdrant:fc1cae7b16d6fd5f431cbce1"},{"table":"knowledge","key":{"id":"enterprise_cb873e2345a508fa44720d93:00309"},"change":"added","before":null,"after":{"id":"enterprise_cb873e2345a508fa44720d93:00309","vector":{"bm25":{"indices":[15211379,21141582,62694798,81869833,114246254,117848935,131900689,136345932,152217691,152900484,176587294,192819851,233592972,257141012,262689147,325678202,352312639,390204765,398400537,402167784,437367475,437666037,448220673,454222729,455026286,486608410,486719200,491396510,502006140,505117043,505715833,523529899,548763890,549128519,549248996,550693654,551536775,559182449,563226112,572399988,610868587,620261599,631232498,636372192,655955059,664433922,672811249,684900361,689873303,715022825,722829366,751262314,757424159,766710245,772165269,780249753,792873749,823134346,827239574,865003533,888000370,917314569,923945757,926244272,951234652,965664421,976217910,997012898,1003647919,1003798966,1009084850,1050007059,1050315610,1058917028,1132748958,1142684427,1143204920,1150939219,1170138678,1228704792,1258039968,1263925004,1297380231,1331432587,1334015030,1356667733,1357846105,1384493885,1413186873,1428545878,1430125705,1466174222,1481705737,1519078073,1575082431,1581361369,1590456296,1617757292,1620849882,1649418775,1710438329,1733190280,1737061407,1751311563,1763574823,1807131503,1807690416,1830646559,1838535212,1838689002,1853176582,1882140086,1889346259,1902323900,1934430699,1945423217,1966814041,1969182875,1979464619,1998848851,2010511940,2021799277,2029138429,2059213458,2064885619,2074315840,2084206835,2128227386,2138315291,2143830595],"values":[1.0228841,1.0228841,1.0228841,1.0228841,1.0228841,1.396479,1.5900621,1.0228841,1.0228841,1.0228841,